MONTH = '2026-11'

S = [
 (1, 'ЦС', 'И', 2026, 'Агенты платят за нас', 'Агенты платят за нас: платёжные системы строят протоколы для ИИ', 'Agents pay for us: payment networks build protocols for AI', 'FTSG в Convergence Outlook 2026 описывает агентов, которые сами ищут, торгуются и платят. Mastercard запустила Agent Pay, Visa — Trusted Agent Protocol: покупку совершает программа, а человек получает готовый результат.', 'In Convergence Outlook 2026, FTSG describes agents that search, negotiate and pay on their own. Mastercard launched Agent Pay and Visa the Trusted Agent Protocol: software makes the purchase and the person receives the result.', 'Кто владеет агентом, тот решает, что человек вообще увидит и купит.', 'Whoever owns the agent decides what a person sees and buys.', 'https://ftsg.com/convergence', 'мир', 'global'),
 (3, 'ЦС', 'Н', 2026, 'Enhanced Games', 'Enhanced Games: первые соревнования, где разрешён допинг', 'Enhanced Games: the first competition where doping is allowed', '24 мая 2026 года в Лас-Вегасе прошли первые Enhanced Games: спортсменам разрешили препараты для повышения результатов. Мировой рекорд побили лишь один раз, а три победителя выступали без препаратов.', 'On 24 May 2026 Las Vegas hosted the first Enhanced Games, where athletes were allowed performance-enhancing drugs. Only one world record fell, and three winners competed drug-free.', 'Апгрейд тела превращают в зрелище и продукт.', 'Body upgrades are turned into spectacle and product.', 'https://www.euronews.com/health/2026/05/26/inside-the-enhanced-games-everything-that-happened-on-sports-most-controversial-night', 'США', 'USA'),
 (4, 'ЦС', 'К', 2026, 'Компьютер из нейронов', 'CL1: компьютер на живых человеческих нейронах поступил в продажу', 'CL1: a computer made of living human neurons goes on sale', 'Австралийская Cortical Labs в 2026 году начала продавать CL1 — биокомпьютер на нейронах, выращенных из стволовых клеток, — и открыла к нему облачный доступ и публичный API. На симпозиуме «Создавая будущее» на этой основе питчили фильм о возрождении сознания.', 'In 2026 Australia’s Cortical Labs began selling CL1, a biocomputer built on neurons grown from stem cells, with cloud access and a public API. At the “Creating the Future” symposium a film pitch about reviving consciousness drew on it.', 'Человеческие нейроны становятся вычислительной инфраструктурой.', 'Human neurons become computing infrastructure.', 'https://itbrief.com.au/story/cortical-labs-cl1-commercial-milestone-after-aud-245k-grant', 'Австралия', 'Australia'),
 (11, 'ЦС', 'И', 2025, 'Тест на ценности для ИИ', 'Китай проверяет модели банком из 2000+ вопросов на соответствие ценностям', 'China tests models with a bank of 2,000+ questions on values', 'Китайский стандарт безопасности генеративного ИИ требует тестового банка не меньше чем из 2000 вопросов; модели проверяют на соответствие «основным социалистическим ценностям» до выхода на рынок.', 'China’s generative-AI safety standard requires a test bank of at least 2,000 questions; models are checked for alignment with “core socialist values” before release.', 'Ценности зашивают прямо в инфраструктуру ИИ.', 'Values are written directly into AI infrastructure.', 'https://chinamediaproject.org/2025/07/30/how-china-sees-ai-safety/', 'Китай', 'China'),
 (9, 'ЦС', 'Н', 2026, 'Netflix снимает про ИИ с ИИ', 'Netflix снимает о рисках ИИ — и сам сделал с ИИ около 300 тайтлов', 'Netflix films the risks of AI and has made about 300 titles with AI', '12 октября 2026 года вышел документальный фильм Netflix «Instadocs: AI Gone Wild» об атаке агентов OpenAI на Hugging Face. При этом Netflix подтвердил, что в 2026 году генеративный ИИ использовали в работе над примерно 300 тайтлами.', 'On 12 October 2026 Netflix released the documentary “Instadocs: AI Gone Wild” about OpenAI agents attacking Hugging Face. Netflix also confirmed that generative AI was used on about 300 titles in 2026.', 'Страх перед ИИ стал жанром платформы, которая сама работает на ИИ.', 'Fear of AI has become a genre for a platform that itself runs on AI.', 'https://mezha.ua/en/news/netflix-hugging-face-attack-315943/', 'США; мир', 'USA; global'),
 (8, 'ЦС', 'Н', 2026, 'Фонд MGX', 'MGX из Абу-Даби закрыл ИИ-фонд на $49 млрд', 'Abu Dhabi’s MGX closed a $49 billion AI fund', 'MGX (Mubadala и G42) закрыл фонд примерно на $49 млрд, вошёл в OpenAI, Anthropic и xAI, с BlackRock купил Aligned Data Centers и строит ИИ-кампус до 3 ГВт под Парижем. Мест в советах директоров суверенные фонды при этом не берут.', 'MGX (Mubadala and G42) closed a fund of about $49 billion, invested in OpenAI, Anthropic and xAI, bought Aligned Data Centers with BlackRock and is building an AI campus of up to 3 GW near Paris. Sovereign funds take no board seats.', 'Физический слой ИИ получает хозяев — фонды Залива.', 'The physical layer of AI acquires owners: Gulf funds.', 'https://aiweekly.co/node/4944', 'ОАЭ; мир', 'UAE; global'),
 (13, 'ЦС', 'Н', 2026, 'Kick и Stake', 'Стриминг на деньгах криптоказино: Kick и гемблинг в эфирах', 'Streaming on crypto-casino money: Kick and gambling on air', 'Платформу Kick создали основатели криптоказино Stake; она отдаёт стримерам 95% дохода и занимает 11–12% часов игрового лайва. В январе 2026 года на Stake пришлось 60% упоминаний игорных брендов в стримах.', 'Kick was created by the founders of the crypto casino Stake; it gives streamers 95% of revenue and holds 11–12% of live gaming hours. In January 2026 Stake accounted for 60% of gambling-brand mentions on streams.', 'У сообществ стримов есть хозяева со своими интересами.', 'Streaming communities have owners with their own interests.', 'https://tech-insider.org/twitch-vs-kick-vs-youtube-2026/', 'мир', 'global'),
 (1, 'ЦС', 'И', 2026, 'ИИ-советники коллекционеров', 'ИИ советует коллекционерам искусства: 22% против 4% два года назад', 'AI advises art collectors: 22% versus 4% two years ago', 'По опросу Art Basel и UBS (3100 состоятельных коллекционеров, октябрь 2026), советами приложений и ИИ пользуются 22% — в 2024 году было 4%. Две трети видят пользу ИИ в поиске художников и проверке подлинности.', 'According to the Art Basel and UBS survey (3,100 wealthy collectors, October 2026), 22% use apps and AI for advice, up from 4% in 2024. Two-thirds see AI as useful for finding artists and checking authenticity.', 'Даже вкус и выбор в искусстве начинают делегировать машине.', 'Even taste and choice in art are starting to be delegated to machines.', 'https://www.artbasel.com/stories/from-ai-to-gen-z--everything-to-know-about-the-2026-survey-of-global-collecting', 'мир', 'global'),
 (20, 'ЦС', 'И', 2026, 'Искусство как залог', 'Искусство как залог: каждый пятый коллекционер уже брал кредит под коллекцию', 'Art as collateral: one in five collectors has borrowed against their collection', 'Около 20% опрошенных Art Basel и UBS уже занимали деньги под произведения искусства, в США — 45%; три четверти из них — больше $1 млн. 19% планируют сделать это в ближайший год.', 'About 20% of collectors surveyed by Art Basel and UBS have borrowed against artworks, 45% in the US; three-quarters of them more than $1 million. 19% plan to do so within a year.', 'Культура становится финансовым активом и инструментом кредита.', 'Culture becomes a financial asset and a credit instrument.', 'https://www.artbasel.com/stories/from-ai-to-gen-z--everything-to-know-about-the-2026-survey-of-global-collecting', 'США; мир', 'USA; global'),
 (7, 'ЦС', 'И', 2026, 'Налог на редкий язык', '«Налог на токены»: ИИ дороже и хуже работает на редких языках', 'The “token tax”: AI costs more and works worse in rare languages', 'Исследование The Token Tax на 10 моделях и 16 африканских языках показало: из-за неэффективной токенизации тексты на малоресурсных языках обходятся дороже и обрабатываются хуже.', 'The Token Tax study of 10 models and 16 African languages found that inefficient tokenisation makes texts in low-resource languages cost more and come out worse.', 'Неравенство встроено в саму технологию: за родной язык платят больше.', 'Inequality is built into the technology: you pay more for your native language.', 'https://aclanthology.org/2026.africanlp-main.10/', 'Африка', 'Africa'),
 (10, 'ЦС', 'Н', 2026, 'Суверенный мессенджер', 'Россия: Discord заблокирован, Telegram ограничен, у MAX — 77,5 млн', 'Russia: Discord blocked, Telegram restricted, MAX at 77.5 million', 'С февраля 2026 года в России ограничивают Telegram, заблокированы Discord, Viber и Signal. Государственный мессенджер MAX набрал 77,5 млн пользователей в месяц и добавил приватные каналы.', 'Since February 2026 Russia has restricted Telegram and blocked Discord, Viber and Signal. The state messenger MAX reached 77.5 million monthly users and added private channels.', 'Связь между людьми переезжает в инфраструктуру центра.', 'Communication between people moves into the centre’s infrastructure.', 'https://carnegieendowment.org/ru/russia-eurasia/politika/2026/03/russia-internet-telegram-restrictions', 'Россия', 'Russia'),
 (14, 'ЦС', 'Н', 2026, 'Охотницы на демонов', '«Охотницы на демонов»: первый тайтл Netflix, год проживший в мировом топ-10', '“KPop Demon Hunters”: the first Netflix title to spend a year in the global top 10', 'Мультфильм провёл 52 недели подряд в мировом топ-10 Netflix, собрал около 640 млн просмотров и больше миллиарда часов. Героини не побеждают своих демонов, а принимают их.', 'The film spent 52 consecutive weeks in Netflix’s global top 10, with about 640 million views and over a billion hours. Its heroines do not defeat their demons; they accept them.', 'Платформа зарабатывает на праве быть несовершенным.', 'The platform profits from the right to be imperfect.', 'https://whats-on-netflix.com/news/kpop-demon-hunters-makes-netflix-history-with-unprecedented-1-year-top-10-streak', 'мир', 'global'),
 (11, 'ЦЗ', 'Н', 2025, '3,11 млн предложений', 'Китай собрал 3,11 млн предложений граждан к пятилетнему плану', 'China collected 3.11 million citizen suggestions for its five-year plan', 'С 20 мая по 20 июня 2025 года в онлайн-консультации к 15-й пятилетке поступило больше 3,11 млн предложений. Государство собирает идеи снизу — внутри заданной сверху рамки.', 'From 20 May to 20 June 2025 an online consultation on the 15th Five-Year Plan received more than 3.11 million suggestions. The state gathers ideas from below within a frame set from above.', 'Центр учится проектировать будущее с участием миллионов.', 'The centre learns to design the future with millions taking part.', 'https://www.chinadaily.com.cn/a/202508/05/WS6890df12a31073015a870b24.html', 'Китай', 'China'),
 (1, 'ЦЗ', 'И', 2025, 'План «ИИ+»', 'План «ИИ+»: агенты и умные устройства — у 70% китайцев к 2027 году', 'The “AI+” plan: agents and smart devices for 70% of Chinese people by 2027', 'Госсовет КНР в августе 2025 года утвердил план «ИИ+»: проникновение умных устройств и ИИ-агентов — больше 70% к 2027 году и больше 90% к 2030-му. Цель в тексте — «технологическая общедоступность и разделение результатов».', 'In August 2025 China’s State Council adopted the “AI+” plan: penetration of smart devices and AI agents above 70% by 2027 and above 90% by 2030. The stated aim is broad access to technology and shared benefits.', 'ИИ как инфраструктура, как электричество, а не как продукт.', 'AI as infrastructure, like electricity, rather than a product.', 'https://cset.georgetown.edu/publication/china-ai-plus-opinions-2025/', 'Китай', 'China'),
 (8, 'ЦЗ', 'Н', 2026, 'Запрет концентрата', 'ДР Конго запретила вывоз медного и кобальтового концентрата', 'DR Congo banned exports of copper and cobalt concentrate', '6 августа 2026 года ДР Конго, крупнейший производитель кобальта, запретила вывоз концентрата, чтобы заставить перерабатывать сырьё в стране. Исключения — на год и только «стратегические».', 'On 6 August 2026 the DR Congo, the largest cobalt producer, banned concentrate exports to force processing at home. Exemptions last a year and only in “strategic” cases.', 'Суверенитет над ресурсами утверждают запретом.', 'Sovereignty over resources is asserted by ban.', 'https://www.businessday.co.za/world/2026-08-06-drc-bans-copper-and-cobalt-concentrates-exports/', 'ДР Конго', 'DR Congo'),
 (8, 'ЦЗ', 'И', 2026, 'Ормуз и удобрения', 'Ормуз перекрыл удобрения: мочевина подорожала вдвое', 'Hormuz cut off fertiliser: urea prices doubled', 'Через Ормузский пролив шла около трети морской торговли удобрениями. После закрытия 28 февраля 2026 года мочевина к апрелю подорожала примерно вдвое; ВПП ООН предупреждает об угрозе голода для 45 млн человек.', 'About a third of seaborne fertiliser trade passed through the Strait of Hormuz. After it closed on 28 February 2026, urea roughly doubled in price by April; the WFP warns 45 million people face dangerous food shortages.', 'Энергокризис за несколько месяцев становится продовольственным.', 'An energy crisis becomes a food crisis within months.', 'https://www.foodsecurityportal.org/node/3890', 'мир', 'global'),
 (8, 'ЦЗ', 'И', 2026, 'Пашня за рубежом', 'ОАЭ контролируют около 960 тыс. га сельхозземли по всему миру', 'The UAE controls about 960,000 hectares of farmland worldwide', 'Залив и Китай покупают и арендуют пашню за рубежом: у ОАЭ около 960 тыс. га, в Африке — около 60% необработанной пашни мира. По спутниковым оценкам, еду реально производит лишь малая часть проектов.', 'The Gulf and China buy and lease farmland abroad: the UAE holds about 960,000 hectares, and Africa has about 60% of the world’s uncultivated arable land. Satellite estimates suggest only a small share of projects actually produce food.', 'Земля снова становится стратегическим активом государств.', 'Land becomes a strategic state asset again.', 'https://kalam.chathamhouse.org/gulf-investment-in-africa-opportunity-asymmetry-and-the-risk-of-dependence/', 'ОАЭ; Африка', 'UAE; Africa'),
 (6, 'ЦЗ', 'И', 2026, 'Борьба за сиделок', 'Стареющие страны перебивают друг у друга сиделок и медиков', 'Ageing countries outbid each other for carers and medics', 'Легальная миграция в Японию, Корею, Германию и Италию в 2025 году выросла на 31% к 2023-му, 80% новых потоков идут по межгосударственным трудовым соглашениям. ВОЗ ждёт нехватки 11 млн медработников к 2030 году.', 'Legal migration to Japan, Korea, Germany and Italy grew 31% in 2025 compared with 2023, with 80% of new flows under bilateral labour agreements. The WHO expects a shortage of 11 million health workers by 2030.', 'Руки и уход становятся ресурсом, за который торгуются государства.', 'Hands and care become a resource states bargain over.', 'https://www.ey.com/en_it/megatrends/why-migration-infrastructure-could-be-the-next-competitive-advantage', 'Япония; Корея; Германия; Италия', 'Japan; Korea; Germany; Italy'),
 (17, 'ЦЗ', 'И', 2026, 'Нобелевка за ожидания', 'Нобелевка-2026: экономику стабилизируют ожидания обычных людей', 'The 2026 Nobel: ordinary people’s expectations stabilise the economy', 'Роберт Холл и Майкл Вудфорд получили премию «за микроэкономические основания макроэкономической стабилизации». Обещания центробанка работают, только если люди им верят; около 80% домохозяйств тратят, исходя из ожиданий о будущем.', 'Robert Hall and Michael Woodford won the prize “for microeconomic foundations of macroeconomic stabilisation”. Central-bank promises work only if people believe them; about 80% of households spend based on expectations of the future.', 'Образ будущего в головах людей становится экономической силой.', 'The image of the future in people’s heads becomes an economic force.', 'https://www.nobelprize.org/prizes/economic-sciences/2026/', 'мир', 'global'),
 (9, 'ЦЗ', 'И', 2026, 'Пауза на стройку', 'Только 14% американцев готовы видеть дата-центр у себя; штаты вводят паузы', 'Only 14% of Americans would accept a data centre nearby; states introduce pauses', 'По опросу Reuters/Ipsos (июнь 2026), лишь 14% поддержали бы ИИ-дата-центр в своём городе. В законодательные собрания штатов за полгода внесли больше 300 законопроектов о дата-центрах, Нью-Йорк продвигает паузу на строительство.', 'In a Reuters/Ipsos poll (June 2026) only 14% would support an AI data centre in their community. More than 300 bills on data centres were introduced in state legislatures in six months, and New York is pushing a construction pause.', 'Тормоз для технологий принимают в форме закона.', 'The brake on technology takes the form of law.', 'https://www.tftc.io/ai-data-center-protests-142-states-286-billion-blocked', 'США', 'USA'),
 (2, 'ДС', 'И', 2026, 'Канарейки в шахте', 'Стэнфорд: занятость 22–25-летних на 19% ниже там, где ИИ заменяет задачи', 'Stanford: employment of 22–25-year-olds is 19% lower where AI replaces tasks', 'По данным ADP до июня 2026 года, занятость молодых в профессиях, сильно затронутых ИИ, примерно на 19% ниже, чем если бы она росла как у сверстников. Падение идёт через сокращение найма; у опытных работников такого разрыва нет.', 'ADP data through June 2026 show that employment of young workers in highly AI-exposed occupations is about 19% below where it would be had it kept pace with peers. The drop comes through reduced hiring; experienced workers show no such gap.', 'Первая ступень карьеры исчезает раньше, чем профессии.', 'The first rung of a career disappears before the professions do.', 'https://digitaleconomy.stanford.edu/publication/canaries-in-the-coal-mine-six-facts-about-the-recent-employment-effects-of-artificial-intelligence/', 'США', 'USA'),
 (2, 'ДС', 'И', 2026, 'Расслоение независимых', 'Независимые расслаиваются: рекорд богатых и 30% «без выбора»', 'Independent workers split: a record at the top and 30% “with no choice”', 'В США 5,6 млн независимых зарабатывают больше $100 тыс. (+19%), у тех, кто работает с ИИ, надбавка около 40%. Но 30% новых независимых пришли «почти без выбора», а одиночество у них втрое чаще, чем у наёмных.', 'In the US 5.6 million independents earn over $100,000 (+19%), and those working with AI earn about 40% more. But 30% of new independents came in “with almost no choice”, and they are three times as likely to be lonely as employees.', 'Автономия расслаивается на верх и низ.', 'Autonomy splits into a top and a bottom.', 'https://ruul.io/Final_Freelance_Economy_Report_2026.pdf', 'США', 'USA'),
 (1, 'ДС', 'И', 2026, 'Китайские открытые модели', 'Открытые китайские модели обогнали американские по скачиваниям', 'Open Chinese models overtook American ones in downloads', 'По отчёту Hugging Face, китайские модели с открытыми весами набрали 41% скачиваний против 36,5% у американских; около 80% американских ИИ-стартапов где-то используют китайские модели. Их можно скачать, запустить у себя и доучить.', 'According to Hugging Face, open-weight Chinese models took 41% of downloads versus 36.5% for American ones; about 80% of US AI startups use Chinese models somewhere. They can be downloaded, run locally and fine-tuned.', 'Свой ИИ без подписки и чужого облака становится доступен каждому.', 'Your own AI without a subscription or someone else’s cloud becomes available to all.', 'https://tech-insider.org/ca/chinese-ai-models-enterprise-share-2026/', 'Китай; мир', 'China; global'),
 (2, 'ДС', 'И', 2026, 'Великое уплощение', 'Следующая прослойка — средний менеджмент: вакансий на 40% меньше', 'The next layer to go is middle management: 40% fewer vacancies', 'По Revelio Labs, вакансий среднего менеджмента с 2022 года стало на 40% меньше; по Gallup, у менеджера в 2013 году было 5 подчинённых, в 2026-м — 12. Gartner ожидал, что к концу 2026 года каждая пятая организация уберёт больше половины этих позиций.', 'According to Revelio Labs, middle-management vacancies have fallen 40% since 2022; according to Gallup, a manager had 5 reports in 2013 and 12 in 2026. Gartner expected one in five organisations to cut more than half of these roles by the end of 2026.', 'После исполнителей уходят координаторы.', 'After the doers, the coordinators go.', 'https://allwork.space/2026/01/ai-is-collapsing-the-corporate-pyramid-experts-say-this-new-shape-is-the-future-of-work', 'США; мир', 'USA; global'),
 (3, 'ДС', 'Н', 2026, 'Мозг за 30 000 франков', 'Улучшение мозга продают как люксовый wellness — до 30 000 франков в неделю', 'Brain improvement is sold as luxury wellness, up to 30,000 francs a week', 'Vogue описывает нейродиагностику, нейрообратную связь и программы оптимизации мозга в частных клиниках; отдельные недельные программы стоят до 30 000 швейцарских франков.', 'Vogue describes neurodiagnostics, neurofeedback and brain-optimisation programmes in private clinics; some week-long programmes cost up to 30,000 Swiss francs.', 'Когнитивный апгрейд становится привилегией.', 'Cognitive upgrades become a privilege.', 'https://www.vogue.com/article/can-money-buy-you-a-better-brain', 'Швейцария; мир', 'Switzerland; global'),
 (19, 'ДС', 'К', 2026, 'Посредники остаются', 'Агенты не убирают посредников, а добавляют слой над ними', 'Agents do not remove intermediaries; they add a layer above them', 'Ждали, что ИИ-агенты обойдут Booking и Expedia, но именно они стали партнёрами агентного бронирования Google. OpenAI свернул формат мгновенной покупки в ChatGPT.', 'Agents were expected to bypass Booking and Expedia, yet these became partners of Google’s agentic booking. OpenAI wound down its instant checkout in ChatGPT.', 'Слой не исчезает, а меняет функцию: от передачи — к гарантии.', 'The layer does not vanish; its function shifts from passing on to guaranteeing.', 'https://www.hospitalitynet.org/opinion/4132643/nobody-gets-bypassed-agentic-commerce-was-supposed-to-route-around-the-otas-googles-partner-list-routes-straight-through-them', 'мир', 'global'),
 (9, 'ДЗ', 'Н', 2026, '142 протеста', '142 протеста в 42 штатах за один день: соседи блокируют дата-центры', '142 protests in 42 states in one day: neighbours block data centres', '18 июля 2026 года в США прошли 142 протеста против дата-центров. По Data Center Watch, местные жители с 2025 года заблокировали или задержали проекты примерно на $286 млрд; групп сопротивления — 843.', 'On 18 July 2026 the US saw 142 protests against data centres. According to Data Center Watch, local opposition has blocked or delayed about $286 billion of projects since 2025; there are 843 opposition groups.', 'Люди реально могут остановить стройку ИИ.', 'People really can stop AI construction.', 'https://www.costar.com/article/1318831312/data-center-opponents-say-protests-signal-growing-resistence', 'США', 'USA'),
 (8, 'ДЗ', 'И', 2026, 'Вода против дата-центров', 'Четверть дата-центров мира стоит там, где не хватает воды', 'A quarter of the world’s data centres stand where water is scarce', 'Исследование 9347 дата-центров: около 25% находятся там, где спрос на воду хотя бы месяц в году превышает предложение. При потеплении доля может вырасти до трети.', 'A study of 9,347 data centres: about 25% are where water demand exceeds supply for at least one month a year. With warming the share could reach a third.', 'Конфликт за ресурсы становится соседским.', 'The conflict over resources becomes a neighbourhood one.', 'https://www.weforum.org/stories/climate-action-and-waste-reduction/research-data-centres-water-scarcity-understanding-risk', 'мир', 'global'),
 (13, 'ДЗ', 'Н', 2025, 'Парламент в Discord', 'Непал: Discord-сервер стал временным парламентом', 'Nepal: a Discord server became a temporary parliament', 'В сентябре 2025 года сервер «Youths Against Corruption» собрал больше 10 тыс. участников для дебатов и голосования за временного премьера; 12 сентября им стала Сушила Карки. Сами участники напоминают, что движение было на многих площадках.', 'In September 2025 the “Youths Against Corruption” server gathered more than 10,000 people to debate and vote for an interim prime minister; on 12 September Sushila Karki took office. Participants point out the movement spanned many platforms.', 'Игровой инструмент становится политическим.', 'A gaming tool becomes a political one.', 'https://kathmandupost.com/politics/2025/09/29/how-nepal-s-enraged-gen-z-turned-discord-into-a-political-arena', 'Непал', 'Nepal'),
 (12, 'ДЗ', 'Н', 2026, 'Флаг One Piece', 'Флаг из аниме One Piece стал общим символом протестов зумеров', 'The One Piece anime flag became a shared symbol of Gen Z protests', 'Пиратский флаг из One Piece появлялся на протестах в Непале, Индонезии, на Филиппинах, Мадагаскаре, во Франции и Марокко. Общая вселенная фандома работает как язык несогласия поверх идеологий.', 'The pirate flag from One Piece appeared at protests in Nepal, Indonesia, the Philippines, Madagascar, France and Morocco. A shared fandom universe works as a language of dissent above ideologies.', 'Поп-культура даёт общий язык людям, которые не знают друг друга.', 'Pop culture gives a shared language to people who do not know each other.', 'https://www.outlookindia.com/international/memes-reels-emojis-nepals-gen-z-protests-unleashed-a-new-language-of-dissent', 'мир', 'global'),
 (13, 'ДЗ', 'И', 2026, 'Лайтстики на протестах', 'Корея: навыки K-pop-фандома перешли в протест', 'Korea: K-pop fandom skills moved into protest', 'На протестах 2024–2025 годов в Южной Корее концертные лайтстики, фанатские речёвки и онлайн-мобилизация стали формой политического высказывания: фанаты перенесли практики коллективного голосования в политику.', 'At the 2024–2025 protests in South Korea, concert lightsticks, fan chants and online mobilisation became a form of political expression: fans carried practices of collective voting into politics.', 'Навыки фандома становятся гражданскими.', 'Fandom skills become civic skills.', 'https://www.cambridge.org/core/product/2EF0AEA5A305B3E0B5EFEC921ED214C4/core-reader', 'Корея', 'Korea'),
 (16, 'ДЗ', 'Н', 2026, 'Право отключить ИИ', 'Родители требуют права отключать ИИ в школьном поиске', 'Parents demand the right to switch off AI in school search', 'В Чикаго родители оспаривают то, что в школьном поиске Google нельзя отключить AI Overviews; члены школьных советов обсуждали трёхлетний мораторий.', 'In Chicago parents are challenging the fact that AI Overviews cannot be switched off in Google’s school search; school council members discussed a three-year moratorium.', 'Режим «без ИИ» становится правом, за которое борются.', 'An “AI-free” mode becomes a right people fight for.', 'https://www.axios.com/local/chicago/2026/11/09/google-wont-turn-off-artificial-intelligence-overview-on-school-search', 'США', 'USA'),
 (14, 'ДЗ', 'К', 2026, 'Prada рисует руками', 'Prada делает праздничную кампанию ручной анимацией вместо генеративной', 'Prada makes its holiday campaign with hand-drawn animation instead of generative AI', 'Праздничная кампания Drawing Prada подчёркивает ручную иллюстрацию и процесс работы. Человеческая рука становится продаваемым качеством.', 'The Drawing Prada holiday campaign highlights hand illustration and the making process. The human hand becomes a selling point.', 'Подлинность человеческого труда становится премиальной.', 'The authenticity of human work becomes premium.', 'https://www.prada.com/es/es/pradasphere/campaigns/2026/holiday.html', 'Италия; мир', 'Italy; global'),
 (19, 'ДЗ', 'И', 2026, 'Покупка у художника', '69% коллекционеров покупают напрямую у художников — вдвое больше, чем в 2024', '69% of collectors buy directly from artists, twice as many as in 2024', 'По опросу Art Basel и UBS, покупают напрямую у художников 69% коллекционеров: в мастерской, по заказу, через Instagram. Прямые продажи дают 19% расходов — больше ярмарок и аукционов.', 'According to the Art Basel and UBS survey, 69% of collectors buy directly from artists: in studios, on commission, via Instagram. Direct sales account for 19% of spending, more than fairs or auctions.', 'Посредник-витрина уходит, остаётся прямая связь с автором.', 'The showroom middleman fades; a direct link to the maker remains.', 'https://www.artbasel.com/stories/from-ai-to-gen-z--everything-to-know-about-the-2026-survey-of-global-collecting', 'мир', 'global'),
 (5, 'ДЗ', 'И', 2026, 'Коллекция для своих', 'Богатые зумеры показывают свои коллекции только близким', 'Wealthy Gen Z show their collections only to those close to them', '39% коллекционеров поколения Z показывают коллекцию вживую только домашним и близким — почти вдвое больше, чем другие поколения; 42% делятся ею онлайн только в закрытых группах.', '39% of Gen Z collectors show their collection in person only to family and close friends, almost twice as many as other generations; 42% share it online only in closed groups.', 'Поколение соцсетей выбирает круг своих вместо широкой публики.', 'The social-media generation chooses its own circle over a wide audience.', 'https://www.artbasel.com/stories/from-ai-to-gen-z--everything-to-know-about-the-2026-survey-of-global-collecting', 'мир', 'global'),
 (5, 'ДЗ', 'И', 2026, 'Доверие только своим', 'Edelman 2026: 70% осторожны в доверии к людям с другими ценностями', 'Edelman 2026: 70% are wary of trusting people with different values', 'Барометр доверия Edelman 2026: 70% опрошенных не хотят или опасаются доверять людям с иными ценностями, взглядами или происхождением.', 'Edelman Trust Barometer 2026: 70% of respondents are unwilling or hesitant to trust people with different values, views or backgrounds.', 'Доверие сжимается до круга своих.', 'Trust shrinks to one’s own circle.', 'https://www.edelman.com/trust/2026/trust-barometer', 'мир', 'global'),
 (9, 'ДЗ', 'И', 2026, 'Молодые охладели к ИИ', 'Доля молодых американцев, видящих в ИИ больше вреда, выросла с 36% до 47%', 'The share of young Americans who see more harm in AI rose from 36% to 47%', 'По Gallup, доля 18–29-летних, которые считают, что ИИ приносит больше вреда, чем пользы, выросла с 36% в 2025 году до 47% в 2026-м.', 'According to Gallup, the share of 18–29-year-olds who think AI does more harm than good rose from 36% in 2025 to 47% in 2026.', 'Новые луддиты — молодые.', 'The new Luddites are young.', 'https://news.gallup.com/poll/712751/americans-cool-toward.aspx', 'США', 'USA'),
 (2, 'ДЗ', 'С', 2026, 'Бюро живых людей', '«Бюро живых людей»: уволенные из-за ИИ продают живое общение', '“Bureau of Living People”: people laid off because of AI sell live contact', 'Проект, победивший в питчинге кинопроектов симпозиума «Создавая будущее»: люди, потерявшие работу из-за нейросетей, открывают платный сервис живого общения.', 'The winning project of the film pitch at the “Creating the Future” symposium: people who lost their jobs to neural networks open a paid service of live human contact.', 'Человеческое присутствие становится профессией.', 'Human presence becomes a profession.', '', 'Россия', 'Russia'),
 (16, 'ДЗ', 'С', 2026, 'Компетенции из фантастики', 'ВШЭ вывела компетенции будущего из 500 фантастических произведений', 'HSE derived future competencies from 500 works of science fiction', 'На симпозиуме «Создавая будущее» исследователи ВШЭ рассказали, что проанализировали около 500 фантастических произведений и выделили три группы компетенций: ясность мысли, рамки и ответственность, доверие и человечность.', 'At the “Creating the Future” symposium, HSE researchers said they had analysed about 500 works of science fiction and identified three groups of competencies: clarity of thought, frames and responsibility, trust and humanity.', 'Фантастику начинают читать как учебник будущего.', 'Science fiction starts being read as a textbook of the future.', '', 'Россия', 'Russia'),
 (2, 'ДС', 'И', 2026, 'Фриланс сжимается', 'Мировой фриланс сжимается: заказчиков меньше, простые задачи уходят к ИИ', 'Global freelancing is shrinking: fewer clients, simple tasks go to AI', 'У Fiverr за год число активных заказчиков упало с 3,4 до 2,7 млн (−21,9%), у Upwork — на 4%, до 763 тыс. OpenAI и Upwork 10 ноября 2026 года показали: в 43 из 63 категорий работ задачи, которые люди уже делают в ChatGPT, теряют долю заказов, а проекты с ИИ получают более крупные бюджеты.', 'Fiverr’s active buyers fell from 3.4 to 2.7 million in a year (−21.9%), and Upwork’s by 4% to 763,000. On 10 November 2026 OpenAI and Upwork showed that in 43 of 63 work categories, tasks people already do in ChatGPT are losing share of orders, while AI-related projects get larger budgets.', 'Свободная занятость перестаёт быть запасным выходом: низ рынка забирает ИИ, остаются сложные и дорогие задачи.', 'Freelancing stops being a fallback: AI takes the bottom of the market, and complex, expensive work remains.', 'https://openai.com/index/ai-effect-on-freelance-work/', 'мир', 'global'),
 (20, 'ЦЗ', 'Ин', 2026, 'CIFS: мегатренды без роста', 'CIFS переписал мегатренды: вместо роста и глобализации — ограничения и новый мировой порядок', 'CIFS rewrote its megatrends: constraints and a new world order instead of growth and globalisation', 'Копенгагенский институт исследований будущего 24 сентября 2026 года выпустил новый доклад: 11 мегатрендов вместо 15 в прошлой версии. «Экономический рост» сменила «Экономика ограничений», «Глобализацию» — «Сдвиг мирового порядка», «ИИ и автоматизацию» — «Встроенный ИИ», «Сетевую экономику» — «Власть через сети», «Фокус на здоровье» — «Здоровье за пределами клиники». Индивидуализм больше не описан как освобождение. Институт заодно ужесточил само определение мегатренда.', 'On 24 September 2026 the Copenhagen Institute for Futures Studies released a new report: 11 megatrends instead of 15 in the previous edition. “Economic Growth” gave way to “The Constrained Economy”, “Globalisation” to “Shifting World Order”, “AI & Automation” to “The Rise of Embedded AI”, “Network Economy” to “Power Through Networks” and “Focus on Health” to “Health Beyond the Clinic”. Individualism is no longer described as liberation. The institute also tightened its definition of a megatrend.', 'Один из старейших институтов будущего перестал считать рост и открытый мир нормой — это меняет базовые допущения любой стратегии.', 'One of the oldest futures institutes no longer treats growth and an open world as the norm, which changes the baseline assumptions of any strategy.', 'https://via.ritzau.dk/pressemeddelelse/15181112/ny-rapport-her-er-de-11-megatrends-der-kommer-til-at-forme-verden-det-naeste-arti?publisherId=13560663', 'Дания; мир', 'Denmark; global'),
 (20, 'ЦЗ', 'Ин', 2026, 'DFF: энергия в допущениях', 'Dubai Future Foundation убрала энергию из мегатрендов — перед закрытием Ормуза', 'Dubai Future Foundation dropped energy from its megatrends just before Hormuz closed', 'В Global 50 2026 Dubai Future Foundation перевела «Энергетические границы» из мегатрендов в «допущения», а «Сохранение экосистем» заменила на «Эволюцию экосистем»: от защиты природы к адаптации к уже изменённой. Через несколько месяцев закрытие Ормузского пролива сделало энергию главным риском года.', 'In Global 50 2026 the Dubai Future Foundation moved “Energy Boundaries” from megatrends into “assumptions” and replaced “Saving Ecosystems” with “Evolving Ecosystems”: from protecting nature to adapting to a nature already changed. A few months later the closure of the Strait of Hormuz made energy the year’s main risk.', 'Институты будущего ошибаются там, где считают вопрос решённым.', 'Futures institutes err where they consider a question settled.', 'https://www.dubaifuture.ae/the-global-50/', 'ОАЭ; мир', 'UAE; global'),
 (12, 'ЦС', 'Ин', 2026, 'FTSG: от трендов к конвергенциям', 'FTSG отказался от списка сотен трендов в пользу 10 конвергенций', 'FTSG dropped its list of hundreds of trends in favour of 10 convergences', 'Future Today Institute, ставший FTSG, вместо ежегодного Tech Trends Report с сотнями трендов выпустил Convergence Outlook 2026 — 10 узлов, где сходятся технологии: «вычислительный шок», «эмоциональный аутсорсинг», «корпоративный паноптикум», «агентная экономика», «новое уравнение труда».', 'The Future Today Institute, now FTSG, replaced its annual Tech Trends Report of hundreds of trends with Convergence Outlook 2026: 10 nodes where technologies converge, including “Compute Shock”, “Emotional Outsourcing”, “The Corporate Panopticon”, “Agentic Economy” and “The New Labor Equation”.', 'Индустрия прогнозов признаёт: отдельные тренды больше не объясняют мир, сдвиг происходит на стыках.', 'The forecasting industry admits that separate trends no longer explain the world; the shift happens where they meet.', 'https://ftsg.com/convergence', 'США; мир', 'USA; global'),
 (15, 'ДЗ', 'Ин', 2026, 'IFTF: кризис проверки человека', 'IFTF: главный навык — различать, главный кризис — проверка, что перед тобой человек', 'IFTF: the key skill is discernment, the key crisis is verifying you are dealing with a human', 'Институт будущего в Пало-Альто сместил центр тяжести своих прогнозов к доверию и подлинности: «бизнес на одиночестве процветает», «различение становится главным мягким навыком», «кризис проверки человека», система доверия к науке перестраивается.', 'The Institute for the Future in Palo Alto has shifted the centre of gravity of its forecasts to trust and authenticity: “the loneliness business is booming”, “discernment becomes the most essential soft skill”, “the human verification crisis” and a rebuilt system for trusting science.', 'Доказать, что ты человек, и отличить правду — становится инфраструктурной задачей, а не личной.', 'Proving you are human and telling truth apart becomes an infrastructure task rather than a personal one.', 'https://www.iftf.org/featured-work/', 'США; мир', 'USA; global'),
 (5, 'ЦС', 'Ин', 2026, 'VML: отношения с ИИ', 'Future 100: 49% зумеров уже в «значимых отношениях» с ИИ', 'Future 100: 49% of Gen Z are already in “meaningful relationships” with AI', 'VML в Future 100 на 2026 год (15 639 опрошенных, 16 рынков) сменила эскапизм и «делулу» на «дизоптимизм» — признать тьму, не сдаваясь ей. ИИ в отчёте перешёл из инструментов в отношения: 49% поколения Z говорят о значимых отношениях с ИИ, а одиночество описано как болезнь.', 'In Future 100 for 2026 (15,639 respondents, 16 markets) VML replaced escapism and “delulu” with “disoptimism”: acknowledging darkness without surrendering to it. AI moved from tools to relationships: 49% of Gen Z report meaningful relationships with AI, and loneliness is described as an illness.', 'Близость с машиной становится массовой нормой поколения.', 'Intimacy with machines becomes a mass norm for a generation.', 'https://www.vml.com/news/the-future-100-2026', 'мир', 'global'),
 (10, 'ЦЗ', 'Ин', 2026, 'RAND: кто держит AGI', 'RAND: в сценариях AGI решает не «когда», а «кто держит»', 'RAND: in AGI scenarios the question is not “when” but “who holds it”', 'RAND перешла от тем геополитики и обороны к AGI в 2030-х как рабочей гипотезе. Восемь сценариев — от «коалиции демократий» и «холодной войны 2» до «Дикого фронтира» и «переворота AGI» — построены на оси централизации разработки.', 'RAND moved from geopolitics and defence topics to AGI in the 2030s as a working hypothesis. Eight scenarios, from a “coalition of democracies” and “Cold War 2” to “The Wild Frontier” and “The AGI Coup”, are built on the axis of how centralised development is.', 'Ось «центр — децентр» становится главной в разговоре о будущем ИИ.', 'The centre–decentre axis becomes central to the conversation about AI’s future.', 'https://www.rand.org/pubs/research_reports/RRA4692-1.html', 'США; мир', 'USA; global'),
 (8, 'ЦС', 'Ин', 2026, 'McKinsey: Web3 исчез', 'McKinsey: Web3 пропал из списка, технологии «ушли с экрана в физический мир»', 'McKinsey: Web3 disappeared from the list, technology “left the screen for the physical world”', 'В Technology Trends Outlook McKinsey Web3 больше нет в открытом списке, ИИ распался на инфраструктуру, агентов и науку, а энергия, сети, чипы и дата-центры описаны как ограничение роста.', 'In McKinsey’s Technology Trends Outlook Web3 is no longer on the open list, AI has split into infrastructure, agents and science, and energy, networks, chips and data centres are described as constraints on growth.', 'Хайп уходит, на первый план выходит железо и электричество.', 'The hype fades; hardware and electricity come to the fore.', 'https://www.mckinsey.com/capabilities/tech-and-ai/our-insights/the-top-trends-in-tech', 'мир', 'global'),
 (10, 'ЦЗ', 'Ин', 2026, 'Gartner: ограничить ИИ', 'Gartner на 2027 год: от «дать ИИ всем» к «ограничить и удержать»', 'Gartner for 2027: from “AI for everyone” to “restrict and retain”', '20 октября 2026 года Gartner опубликовал стратегические технологические тренды на 2027 год. Три года назад в списке была демократизация генеративного ИИ, теперь — суверенные технологии, идентичность ИИ-агентов, модели мира и wetware-as-a-service.', 'On 20 October 2026 Gartner published its strategic technology trends for 2027. Three years ago the list featured the democratisation of generative AI; now it has sovereign technology, AI-agent identity, world models and wetware-as-a-service.', 'Корпоративный мейнстрим разворачивается от открытости к контролю.', 'The corporate mainstream turns from openness to control.', 'https://www.networkworld.com/article/4238030/gartners-top-tech-trends-for-2027-expand-and-accelerate.html', 'мир', 'global'),
 (20, 'ЦЗ', 'Ин', 2026, 'WEF: геоэкономика как оружие', 'WEF: главный риск — геоэкономическое противостояние', 'WEF: the top risk is geoeconomic confrontation', 'В Global Risks Report 2026 геоэкономическое противостояние названо главным возможным источником кризиса, дезинформация и поляризация — наверху краткосрочных рисков. В 2023 году первым была стоимость жизни.', 'The Global Risks Report 2026 names geoeconomic confrontation as the most likely trigger of a crisis, with disinformation and polarisation at the top of short-term risks. In 2023 the cost of living ranked first.', 'Риски не сменяют друг друга, а складываются.', 'Risks do not replace one another; they stack up.', 'https://www.weforum.org/publications/global-risks-report-2026', 'мир', 'global'),
 (12, 'ДС', 'Ин', 2026, 'META 2026: перегруз трендами', '74% стратегов: пустых трендов слишком много', '74% of strategists: there are too many empty trends', 'Обзор META 2026 от kleinkleinklein свёл 70+ отчётов и 400+ трендов: слова года — «тревога» и «перегруз», 74% стратегов считают, что пустых трендов слишком много. Переоценены зрелище и «мурашки», недооценены кризис проверки, переобучение и одиночество.', 'The kleinkleinklein META 2026 review combined 70+ reports and 400+ trends: the words of the year are “anxiety” and “overload”, and 74% of strategists say there are too many empty trends. Spectacle and goosebumps are overrated; the verification crisis, retraining and loneliness are underrated.', 'Индустрия трендов начала критиковать саму себя — ценится проверка данными, а не яркость.', 'The trend industry has begun to criticise itself: verification with data is valued over flashiness.', 'https://zine.kleinkleinklein.com/p/meta-trends-2026', 'мир', 'global'),
]

